#!/usr/bin/env sh
# Validates a commit message (file path in $1) or a PR title (string in
# $COMMIT_TITLE) against Conventional Commits. See docs/standards/GIT_WORKFLOW.md.
# Local use: .standards/bin/check-commit-msg.sh .git/COMMIT_EDITMSG
set -eu
# Count characters, not bytes, so non-ASCII subjects get the same 72-char limit.
export LC_ALL=C.UTF-8

if [ -n "${COMMIT_TITLE:-}" ]; then
  subject=$COMMIT_TITLE
else
  subject=$(grep -v '^#' "$1" | sed -n '/./{p;q;}')
fi

# Messages generated by git itself are accepted as-is.
case "$subject" in
  "Merge "*|"Revert \""*|"fixup! "*|"squash! "*|"amend! "*) exit 0 ;;
esac

pattern='^(feat|fix|perf|refactor|docs|test|build|ci|chore|revert)(\([a-z0-9._/-]+\))?!?: [^ ].{0,71}$'
if printf '%s' "$subject" | grep -Eq "$pattern"; then
  exit 0
fi

cat >&2 <<MSG
✗ invalid commit message: "$subject"

  expected: <type>(<scope>): <subject>   (subject ≤ 72 chars)
  types:    feat fix perf refactor docs test build ci chore revert
  example:  fix(billing): pass request ctx to Stripe calls

  see docs/standards/GIT_WORKFLOW.md
MSG
exit 1
